import{_ as t,o as p,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const N=JSON.parse('{"title":"Ceph Days NYC 2023: Ceph at CERN: A Ten-Year Retrospective","description":"","frontmatter":{"title":"Ceph Days NYC 2023: Ceph at CERN: A Ten-Year Retrospective","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-18T00:00:00.000Z","tags":["Ceph","分布式存储","CERN","存储","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_Ceph_at_CERN_-_A_Ten-Year_Retrospective.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_Ceph_at_CERN_-_A_Ten-Year_Retrospective.md","lastUpdated":1780459816000}'),a={name:"posts/2023/Ceph_Days_NYC_2023_-_Ceph_at_CERN_-_A_Ten-Year_Retrospective.md"};function C(r,e,s,_,o,n){return p(),l("div",null,[...e[0]||(e[0]=[i('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph在CERN的十年回顾：经验与挑战</p><p><strong>主讲人：</strong> 来自加拿大维多利亚大学的工程师，自2008年起在CERN工作，曾管理Ceph项目，现为CERN的首席IT架构师，同时也是Ceph基金会的董事会成员和执行委员会成员。</p><p><strong>会议内容概述：</strong></p><ol><li><p><strong>个人背景介绍：</strong></p><ul><li>主讲人自2008年起在CERN工作，管理Ceph项目直至去年，现为CERN的首席IT架构师。</li><li>2021年起担任Ceph基金会执行委员会成员。</li><li>计划于2023年4月移居温哥华，加入Iwakim公司，帮助在北美建立Klysto。</li></ul></li><li><p><strong>CERN与Ceph的结合：</strong></p><ul><li>展示了CERN的大型强子对撞机（LHC）的照片，解释了CERN的主要研究活动。</li><li>讨论了Ceph在CERN的存储解决方案中的重要性，特别是在处理大量物理数据时的应用。</li></ul></li><li><p><strong>Ceph在CERN的十年回顾：</strong></p><ul><li>从2013年开始，Ceph在CERN的使用从300TB的试点项目发展到2016年的6PB集群。</li><li>2016年后，Ceph集群规模持续扩大，目前拥有约17个集群和100PB的存储容量。</li><li>强调了Ceph在CERN基础设施中的关键作用，特别是在OpenStack和CFS的生产环境中。</li></ul></li><li><p><strong>挑战与成功故事：</strong></p><ul><li>讨论了实施Ceph时面临的挑战，包括硬件兼容性、网络配置和性能优化。</li><li>分享了Ceph在CERN的成功案例，如通过改进的Erasure Coding和对象分条技术提高数据处理效率。</li></ul></li><li><p><strong>未来方向与教训：</strong></p><ul><li>强调了持续的监控和维护、测试和社区协作的重要性。</li><li>提出了对Ceph未来发展的建议，包括改进的性能优化和更智能的集群管理工具。</li></ul></li></ol><p><strong>决定事项：</strong></p><ul><li>继续支持Ceph的发展，特别是在性能和可扩展性方面的改进。</li><li>加强与Ceph社区的协作，共享最佳实践和技术更新。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>主讲人将在2023年4月加入Iwakim公司，继续在北美推广Ceph技术。</li><li>CERN将继续与Ceph社区合作，参与会议和研讨会，以推动Ceph技术的进一步发展。</li></ul><p><strong>总结：</strong> 主讲人通过其在CERN的十年经验，分享了Ceph在大型科研环境中的应用和挑战，强调了Ceph作为分布式存储解决方案的强大功能和社区支持的重要性。通过持续的技术改进和社区协作，Ceph有望在未来继续在科研和工业领域发挥关键作用。</p>',11)])])}const R=t(a,[["render",C]]);export{N as __pageData,R as default};
